// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { ArrowLeftRightIcon, CheckIcon, ChevronDownIcon, CopyIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  CATEGORIES,
  CATEGORY_INDEX,
  FROM_INDEX,
  STATES,
  TO_INDEX,
  UNIT_NAMES,
  VALUE,
} from './script'

const build: Build = ({ tl, q, step, final, move, click, type, scramble, wait, cursorOut }) => {
  const result = (value: string) =>
    scramble('result-value', value, { at: '<0.1', duration: 0.5, chars: '0123456789.' })
  const pick = (menu: string, index: number) => {
    move(menu, { ax: 0.4 })
    click(menu)
    tl.fromTo(
      q(`${menu}-menu`),
      { opacity: 0, y: -4 },
      { opacity: 1, y: 0, duration: 0.2, immediateRender: false },
      '<',
    )
    move(`${menu}-item-${index}`, { ax: 0.3, at: '+=0.15' })
    click(`${menu}-item-${index}`)
    tl.to(
      q(`${menu}-item-${index}`),
      { backgroundColor: 'var(--demo-tint-12)', duration: 0.1 },
      '<',
    )
    tl.to(q(`${menu}-menu`), { opacity: 0, duration: 0.15 }, '+=0.1')
  }

  step(0)
  pick('cat', CATEGORY_INDEX)
  tl.set(q('cat-value'), { text: CATEGORIES[CATEGORY_INDEX].name }, '<')
  tl.set(q('from-value'), { text: STATES.category.from }, '<')
  tl.set([q('to-value'), q('to-name')], { text: STATES.category.to }, '<')
  result(STATES.category.result)

  step(1, '+=0.5')
  pick('from', FROM_INDEX)
  tl.set(q('from-value'), { text: STATES.from.from }, '<')
  result(STATES.from.result)
  pick('to', TO_INDEX)
  tl.set([q('to-value'), q('to-name')], { text: STATES.to.to }, '<')
  result(STATES.to.result)

  step(2, '+=0.5')
  move('value', { ax: 0.3 })
  click('value')
  tl.to(q('value-text'), { backgroundColor: 'rgba(56,189,248,0.35)', duration: 0.1 }, '+=0.1')
  tl.set(q('value-text'), { text: '', backgroundColor: 'rgba(56,189,248,0)' }, '+=0.25')
  type('value-text', String(VALUE), { speed: 0.12 })
  result(STATES.typed.result)
  move('swap', { at: '+=0.6' })
  click('swap')
  tl.to(q('swap-icon'), { rotate: 180, duration: 0.4, ease: 'power3.inOut' }, '<')
  tl.to([q('from-value'), q('to-value')], { opacity: 0, duration: 0.12 }, '<')
  tl.set(q('from-value'), { text: STATES.to.to }, '>')
  tl.set([q('to-value'), q('to-name')], { text: STATES.from.from }, '<')
  tl.to([q('from-value'), q('to-value')], { opacity: 1, duration: 0.15 }, '<')
  result(STATES.swapped.result)
  move('copy', { at: '+=0.5' })
  click('copy')
  tl.to(q('copy-icon'), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q('copied-icon'),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)', immediateRender: false },
    '<',
  )
  cursorOut('+=0.3')
  final()
  wait(1.2)

  tl.set([q('cat-menu'), q('from-menu'), q('to-menu'), q('copied-icon')], { opacity: 0 }, 0)
}

function Trigger({ d, value, className }: { d: string; value: string; className?: string }) {
  return (
    <span
      data-d={d}
      className={`flex h-9 items-center justify-between gap-1 rounded-lg border border-line-strong bg-canvas/80 px-2.5 text-[11px] text-ink ${className ?? ''}`}
    >
      <span data-d={`${d}-value`} className="truncate">
        {value}
      </span>
      <ChevronDownIcon className="size-3 shrink-0 text-muted" />
    </span>
  )
}

function Menu({ d, items, className }: { d: string; items: string[]; className?: string }) {
  return (
    <span
      data-d={`${d}-menu`}
      className={`absolute top-full z-10 mt-1 rounded-md border border-line-strong bg-elevated p-0.5 opacity-0 shadow-2xl ${className ?? ''}`}
    >
      {items.map((item, index) => (
        <span
          key={item}
          data-d={`${d}-item-${index}`}
          className="block rounded px-2 text-[9.5px] leading-[15px] text-ink-soft"
        >
          {item}
        </span>
      ))}
    </span>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Unit Converter switching to Data, converting ${VALUE} gigabytes to ${STATES.typed.result} gibibytes, then swapping the direction`}
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex flex-col gap-3.5 pt-1">
          <div className="relative">
            <Trigger d="cat" value={CATEGORIES[0].name} />
            <Menu d="cat" items={CATEGORIES.map((entry) => entry.name)} className="left-0 w-40" />
          </div>
          <div className="flex items-center gap-1.5">
            <span
              data-d="value"
              className="flex h-9 min-w-0 flex-1 items-center rounded-lg border border-line-strong bg-canvas/80 px-2.5 font-mono text-[13px] text-ink"
            >
              <span data-d="value-text">{STATES.start.value}</span>
              <span className="ml-px h-3.5 w-px animate-pulse bg-ink-soft" />
            </span>
            <span className="relative">
              <Trigger d="from" value={STATES.start.from} className="w-[132px]" />
              <Menu d="from" items={UNIT_NAMES} className="left-0 w-[132px]" />
            </span>
            <span
              data-d="swap"
              className="flex size-9 items-center justify-center rounded-lg text-ink-soft"
            >
              <ArrowLeftRightIcon data-d="swap-icon" className="size-4" />
            </span>
            <span className="relative">
              <Trigger d="to" value={STATES.start.to} className="w-[132px]" />
              <Menu d="to" items={UNIT_NAMES} className="right-0 w-[132px]" />
            </span>
          </div>
          <div className="flex items-center justify-between rounded-xl border border-line bg-ink/[0.04] px-4 py-6">
            <code data-d="result-value" className="font-mono text-[30px] font-semibold text-ink">
              {STATES.start.result}
            </code>
            <span className="flex items-center gap-2">
              <span data-d="to-name" className="text-[11px] text-muted">
                {STATES.start.to}
              </span>
              <span data-d="copy" className="relative size-3.5 text-muted">
                <CopyIcon data-d="copy-icon" className="absolute inset-0 size-3.5" />
                <CheckIcon
                  data-d="copied-icon"
                  className="absolute inset-0 size-3.5 text-[var(--accent)] opacity-0"
                />
              </span>
            </span>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
